<template><AppShell><view class="page-heading people-cover-heading"><text class="eyebrow">山河人物 / PEOPLE & PLACES</text><text class="page-title">循山河，读人物</text><text class="muted">按省份寻找名字，再走近一段真实的人生。</text></view><view class="archive-overview"><view><text class="archive-stat">{{records.length}}</text><text>收录人物</text></view><view><text class="archive-stat">{{dossiers.length}}</text><text>详细档案</text></view><view><text class="archive-stat">5</text><text>IP专项组</text></view></view><view class="registry-scope"><text>全国名单、15份详细档案、5组IP涉及的9名人物已合并去重。未分省人物也计入总数；数字仅表示本项目收录范围。</text></view><view class="filter-panel directory-filter"><view class="search-field"><image src="/static/icons/search.png"/><input v-model="query" placeholder="搜索姓名、别名或籍贯" confirm-type="search" aria-label="搜索人物"/><button v-if="query" class="clear-button" @tap="query=''">×</button></view><view class="archive-controls"><view class="chips directory-segments"><button v-for="m in modes" :key="m.id" :class="{active:mode===m.id}" :aria-pressed="mode===m.id" @tap="mode=m.id">{{m.name}}</button></view><picker v-if="mode==='directory'" :value="options.findIndex(p=>p.code===code)" :range="options" range-key="label" @change="selectProvince"><button class="province-filter" aria-label="选择籍贯省份"><image src="/static/icons/pin.png" mode="aspectFit"/><text>{{selectedLabel}}</text><text class="filter-chevron">⌄</text></button></picker></view></view><template v-if="mode==='directory'"><view class="directory-dossiers quick-directory"><button class="quick-toggle" :aria-expanded="quickOpen" aria-controls="quick-people" @tap="quickOpen=!quickOpen"><view><text class="quick-title">重点人物 · 快速阅读</text><text class="quick-subtitle">按人物地域分组，籍贯与出生地分别注明，不重复计数。</text></view><view class="quick-toggle-end"><text class="quick-count">{{quickCount}}份档案</text><text class="quick-state">{{quickOpen?'收起':'展开'}} <text :class="['quick-chevron',{expanded:quickOpen}]">⌄</text></text></view></button><view v-if="quickOpen" id="quick-people" class="quick-content"><view v-for="section in quickSections" :key="section.name" class="quick-row"><text class="quick-region">{{section.name}}</text><view class="dossier-links"><button v-for="p in section.items" :key="p.id" class="dossier-link" @tap="go('person',{id:p.id})">{{p.name}}</button></view></view><text v-if="!quickCount" class="small">没有匹配的详细档案，可继续查看全国名单。</text></view></view><view class="list-summary"><text>按来源所记籍贯分省</text></view><view v-for="section in sections" :key="section.code" class="province-section"><view class="section-head"><text>{{section.name}}</text><text class="small">{{section.items.length}} 条</text></view><view class="archive-name-grid"><button v-for="p in section.items" :key="p.id" :class="['archive-name','name-record',{ 'has-dossier':Boolean(detailFor(p)) }]" :aria-label="'查看'+p.name+'资料'" @tap="open(p)"><text class="name-monogram" aria-hidden="true">{{p.name.slice(0,1)}}</text><view class="name-record-copy"><view class="name-record-title"><text class="registry-name">{{p.name}}</text><text v-if="detailFor(p)" class="dossier-mark">详细档案</text></view><text class="name-date">出生 <text>{{p.birthText||'未载'}}</text></text><text class="name-origin">{{p.originText||'籍贯未载'}}</text></view><text class="name-record-arrow" aria-hidden="true">↗</text></button></view></view><StatePanel v-if="!filtered.length" title="暂无对应收录人物" message="试试其他姓名或省份。未收录不代表该地区没有英雄人物。"/></template><template v-else-if="mode==='detail'"><text class="muted">详细档案按人物地域分组；每份档案分别注明籍贯或出生地域。</text><view v-for="section in detailSections" :key="section.name" class="province-section"><view class="section-head"><text>{{section.name}}</text><text class="small">{{section.items.length}} 份档案</text></view><view class="people-grid"><PersonCard v-for="(p,i) in section.items" :key="p.id" :person="p" :index="i"/></view></view><StatePanel v-if="!detailSections.length" title="暂无对应详细档案" message="可切换全国名单继续搜索。"/></template><template v-else><view class="registry-scope"><text>五组IP专项不额外增加人数。狼牙山五壮士为一个设计组，包含五名成员；形象与漫画属于艺术化表达。</text></view><view class="ip-topic-grid"><view v-for="g in visibleIP" :key="g.group" class="ip-topic"><image class="ip-card-image" :src="topicPhotos[g.group].src" mode="aspectFill" :aria-label="topicPhotos[g.group].caption"/><text class="eyebrow">专题 / {{g.group}} · {{topicPhotos[g.group].label}}</text><text class="section-title">{{g.name}}</text><text class="small">{{g.note}}</text><text v-if="g.group==='LYS'" class="topic-photo-note">葛振林、宋学义两位成员合影</text><button class="topic-source" @tap="photoSource(g.group)">图注与来源 ↗</button><view class="next-actions"><button class="outline" @tap="go('ip',{group:g.group})">走进人物</button><button v-if="g.group==='JZY'" class="outline" @tap="go('story')">针线里的黎明 · 互动故事</button><button class="primary" @tap="go('learning',{group:g.group})">学习挑战</button></view></view></view><StatePanel v-if="!visibleIP.length" title="暂无对应IP专项" message="请尝试其他姓名。"/></template></AppShell></template>
<script setup>
import {ref,computed} from 'vue';import topicPhotos from '../data/专题真人照片.json';import AppShell from './AppShell.vue';import PersonCard from './PersonCard.vue';import StatePanel from './StatePanel.vue';import dossiers from '../data/详细档案索引.json';import {provinces,shortName,people as records} from '../lib/全国收录.js';import {go} from '../lib/navigation.js';
function photoSource(group){const a=topicPhotos[group];uni.showModal({title:'专题图片资料',content:a.caption+'\n'+a.credit,confirmText:'复制来源',success:r=>{if(r.confirm)uni.setClipboardData({data:a.sourceURL})}})}
const quickOpen=ref(false);
const query=ref(''),code=ref(''),mode=ref('directory'),modes=[{id:'directory',name:'全国名单'},{id:'detail',name:'详细档案'},{id:'ip',name:'IP专项'}];
const options=[{code:'',label:'全部省份'},...provinces.map(p=>({code:p.code,label:shortName(p.name)})),{code:'unknown',label:'未分省人物'}],selectedLabel=computed(()=>options.find(p=>p.code===code.value)?.label||'全部省份');
function selectProvince(e){code.value=options[Number(e.detail.value)]?.code||''}
const matches=p=>!query.value.trim()||[p.name,...(p.aliases||[]),p.originText||''].some(s=>s.includes(query.value.trim()));
const filtered=computed(()=>records.filter(p=>(!code.value||(code.value==='unknown'?!p.provinceCode:p.provinceCode===code.value))&&matches(p)));
const sections=computed(()=>[...provinces,{code:'',name:'未分省人物'}].map(p=>({...p,items:filtered.value.filter(x=>x.provinceCode===p.code)})).filter(p=>p.items.length));
const detailSections=computed(()=>[...new Set(dossiers.map(p=>p.province))].map(name=>({name:name==='待核'?'出生地域未载':name+' · 人物地域',items:dossiers.filter(p=>p.province===name&&matches(p)&&(mode.value!=='directory'||!code.value||(code.value==='unknown'?name==='待核':shortName(provinces.find(x=>x.code===code.value)?.name||'')===name)))})).filter(p=>p.items.length));
const quickSections=computed(()=>[...new Set(dossiers.map(p=>p.province))].map(name=>({name:name==='待核'?'出生地域未载':name,items:dossiers.filter(p=>p.province===name&&matches(p))})).filter(s=>s.items.length));
const quickCount=computed(()=>quickSections.value.reduce((n,s)=>n+s.items.length,0));
const nameCounts=new Map();for(const p of records)nameCounts.set(p.name,(nameCounts.get(p.name)||0)+1);const detailMap=new Map(dossiers.filter(p=>nameCounts.get(p.name)===1).map(p=>[p.name,p]));
function detailFor(p){return dossiers.find(d=>d.id===p.readingId)||null}
function open(p){const group=({'瞿秋白':'QQB','宋振中':'SZZ','陆定一':'LDY','江竹筠':'JZY','江姐':'JZY','马宝玉':'LYS','葛振林':'LYS','宋学义':'LYS','胡德林':'LYS','胡福才':'LYS'})[p.name];if(group){go('ip',{group});return}const detail=detailFor(p);if(detail)go('person',{id:detail.id});else if(p.ipGroup)go('ip',{group:p.ipGroup});else go('registry',{id:p.id})}
const ipGroups=[{group:'QQB',name:'瞿秋白',id:'P009',note:'江苏常州 · 人物形象专项'},{group:'LYS',name:'狼牙山五壮士',note:'五名成员 · 团体专项；详细档案待整理'},{group:'SZZ',name:'宋振中',id:'P004',note:'江苏徐州 · 小萝卜头'},{group:'LDY',name:'陆定一',id:'P014',note:'江苏无锡 · 人物形象专项'},{group:'JZY',name:'江竹筠',aliases:['江姐'],note:'江姐 · 人物专项；详细档案待整理'}],visibleIP=computed(()=>ipGroups.filter(matches));
</script>
